    }
    public static int PxSeenBegin(emon.Port.Cells seen, int nobj) {
        // Start a traversal that must not visit an indirect object twice. `seen` holds an
        // EPOCH in cell 0 and one cell an object number: a mark is the epoch's value, so
        // starting again clears every mark at no cost. Each traversal that can be open at
        // the same time as another needs its own `seen`.
        while (emon.Port.CellsLen(seen) < (nobj + 1)) {
            emon.Port.CellsPush(seen, 0);
        }
        emon.Port.CellsSet(seen, 0, emon.Port.CellsAt(seen, 0) + 1);
        return 0;
    }
    public static int PxSeenMark(emon.Port.Cells seen, int num) {
        // 1 when object `num` was already marked in this traversal, else marks it and
        // answers 0. An object number the table does not cover is never marked (depth
        // bounds the walk that meets it).
        if (num <= 0) {
            return 0;
        }
        if (num >= emon.Port.CellsLen(seen)) {
            return 0;
        }
        if (emon.Port.CellsAt(seen, num) == emon.Port.CellsAt(seen, 0)) {
            return 1;
        }
        emon.Port.CellsSet(seen, num, emon.Port.CellsAt(seen, 0));
        return 0;
    }
    internal static int PxNtInLimits(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, int node, int key) {
        // 0 when the node's /Limits exclude `key`; 1 when they include it or say nothing.
        int lim = PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxLimits());
        int e = 0;
        int lo = 0;
        int hi = 0;
        if (lim == 0) {
            return 1;
        }
        if (Pdflex.PlKindOf(ar, lim) != 6) {
            return 1;
        }
        e = PxNth(ar, lim, 0);
        lo = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
        e = PxNth(ar, lim, 1);
        hi = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
        if ((lo == 0) || (hi == 0)) {
            return 1;
        }
        if (PxBytesCmp(ar, key, lo) < 0) {
            return 0;
        }
        if (PxBytesCmp(ar, key, hi) > 0) {
            return 0;
        }
        return 1;
    }
    internal static int PxNtNode(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, int node, int key, int depth, int honor) {
        // Search one node of a name tree for `key`: the RAW value, 0 when it is not here.
        if (depth > PxDepth) {
            return 0;
        }
        if (node == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, node) != 7) {
            return 0;
        }
        int left = emon.Port.CellsAt(idx, 3);
        int tot = emon.Port.CellsAt(idx, 6);
        if (left <= 0) {
            return 0;
        }
        if (tot <= 0) {
            return 0;
        }
        emon.Port.CellsSet(idx, 3, left - 1);
        emon.Port.CellsSet(idx, 6, tot - 1);
        if (honor == 1) {
            if (PxNtInLimits(src, ar, dc, a, b, st, node, key) == 0) {
                return 0;
            }
        }
        int names = Pdfdoc.PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnNames());
        int kids = Pdfdoc.PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnKids());
        int k = 0;
        int v = 0;
        int kr = 0;
        int r = 0;
        if ((names != 0) && (Pdflex.PlKindOf(ar, names) == 6)) {
            k = Pdflex.PlFirst(ar, names);
            while (k != 0) {
                v = Pdflex.PlNext(ar, k);
                if (v == 0) {
                    return 0;
                }
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                if (kr != 0) {
                    if (PxBytesCmp(ar, kr, key) == 0) {
                        return v;
                    }
                }
                k = Pdflex.PlNext(ar, v);
            }
        }
        if ((kids != 0) && (Pdflex.PlKindOf(ar, kids) == 6)) {
            k = Pdflex.PlFirst(ar, kids);
            while (k != 0) {
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                r = PxNtNode(src, ar, dc, a, b, st, idx, kr, key, depth + 1, honor);
                if (r != 0) {
                    return r;
                }
                k = Pdflex.PlNext(ar, k);
            }
        }
        return 0;
    }
    public static int PxNtFind(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, int key) {
        // The raw value under `key` (a string or name object) in the catalog's /Names
        // /Dests tree, 0 when absent. /Limits narrow the search; a miss is searched again
        // without them (a producer that wrote them wrong), inside the same node budget.
        int root = emon.Port.CellsAt(idx, 2);
        int r = 0;
        if (root == 0) {
            return 0;
        }
        emon.Port.CellsSet(idx, 3, PxNodes);
        r = PxNtNode(src, ar, dc, a, b, st, idx, root, key, 0, 1);
        if (r != 0) {
            return r;
        }
        emon.Port.CellsSet(idx, 3, PxNodes);
        return PxNtNode(src, ar, dc, a, b, st, idx, root, key, 0, 0);
    }
    public static int PxDictFindBytes(emon.Port.Cells ar, emon.Port.Cells idx, int dict, int key) {
        // The raw value of the dictionary entry whose KEY NAME has the bytes of `key` (a
        // string or name object): the old-style /Dests dictionary. 0 when absent. Each entry
        // looked at is charged to the run's lookup budget (idx cell 6).
        if (dict == 0) {
            return 0;
        }
        int d = dict;
        int k = 0;
        int v = 0;
        if (Pdflex.PlKindOf(ar, d) == 8) {
            d = Pdflex.PlStreamDict(ar, d);
        }
        if (Pdflex.PlKindOf(ar, d) != 7) {
            return 0;
        }
        k = Pdflex.PlFirst(ar, d);
        while (k != 0) {
            if (emon.Port.CellsAt(idx, 6) <= 0) {
                return 0;
            }
            emon.Port.CellsSet(idx, 6, emon.Port.CellsAt(idx, 6) - 1);
            v = Pdflex.PlNext(ar, k);
            if (PxBytesCmp(ar, k, key) == 0) {
                return v;
            }
            if (v == 0) {
                k = 0;
            } else {
                k = Pdflex.PlNext(ar, v);
            }
        }
        return 0;
    }
    public static int PxDictFindPlain(emon.Port.Cells ar, int dict, int key) {
        // `px-dict-find-bytes` without the budget: for a dictionary the caller knows is small
        // (an annotation's appearance states).
        if (dict == 0) {
            return 0;
        }
        int d = dict;
        int k = 0;
        int v = 0;
        if (Pdflex.PlKindOf(ar, d) == 8) {
            d = Pdflex.PlStreamDict(ar, d);
        }
        if (Pdflex.PlKindOf(ar, d) != 7) {
            return 0;
        }
        k = Pdflex.PlFirst(ar, d);
        while (k != 0) {
            v = Pdflex.PlNext(ar, k);
            if (PxBytesCmp(ar, k, key) == 0) {
                return v;
            }
            if (v == 0) {
                k = 0;
            } else {
                k = Pdflex.PlNext(ar, v);
            }
        }
        return 0;
    }
    internal static int PxNtCollect(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, int node, int depth, emon.Port.Cells @out) {
        // Every (key handle, value handle) pair of a name tree, in tree order, appended to
        // `out` (two cells a pair); the handles are the arena's, raw.
        if (depth > PxDepth) {
            return 0;
        }
        if (node == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, node) != 7) {
            return 0;
        }
        int left = emon.Port.CellsAt(idx, 3);
        if (left <= 0) {
            return 0;
        }
        emon.Port.CellsSet(idx, 3, left - 1);
        int names = Pdfdoc.PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnNames());
        int kids = Pdfdoc.PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnKids());
        int k = 0;
        int v = 0;
        int kr = 0;
        if ((names != 0) && (Pdflex.PlKindOf(ar, names) == 6)) {
            k = Pdflex.PlFirst(ar, names);
            while (k != 0) {
                v = Pdflex.PlNext(ar, k);
                if (v == 0) {
                    k = 0;
                } else {
                    kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                    if ((kr != 0) && ((Pdflex.PlKindOf(ar, kr) == 5) || (Pdflex.PlKindOf(ar, kr) == 4))) {
                        emon.Port.CellsPush(@out, kr);
                        emon.Port.CellsPush(@out, v);
                    }
                    k = Pdflex.PlNext(ar, v);
                }
            }
        }
        if ((kids != 0) && (Pdflex.PlKindOf(ar, kids) == 6)) {
            k = Pdflex.PlFirst(ar, kids);
            while (k != 0) {
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                PxNtCollect(src, ar, dc, a, b, st, idx, kr, depth + 1, @out);
                k = Pdflex.PlNext(ar, k);
            }
        }
        return 0;
    }
    public static int PxDestsCollect(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells @out) {
        // Every named destination: first the old-style /Dests dictionary's (key handle,
        // value handle), then the name tree's. Appended to `out`, cleared first.
        emon.Port.CellsDrop(@out, 0);
        int dd = emon.Port.CellsAt(idx, 1);
        int k = 0;
        int v = 0;
        int n = 0;
        if (dd != 0) {
            k = Pdflex.PlFirst(ar, dd);
            while (k != 0) {
                v = Pdflex.PlNext(ar, k);
                if (v == 0) {
                    k = 0;
                } else {
                    if (Pdflex.PlKindOf(ar, k) == 4) {
                        emon.Port.CellsPush(@out, k);
                        emon.Port.CellsPush(@out, v);
                    }
                    k = Pdflex.PlNext(ar, v);
                }
            }
        }
        emon.Port.CellsSet(idx, 3, PxNodes);
        PxNtCollect(src, ar, dc, a, b, st, idx, emon.Port.CellsAt(idx, 2), 0, @out);
        n = emon.Port.CellsLen(@out) / 2;
        return n;
    }
    public static int PxNnCollect(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, int node, int depth, emon.Port.Cells @out) {
        // Every (integer key, value handle) of a number tree, in tree order, appended to
        // `out` two cells a pair (the value handle is raw).
        if (depth > PxDepth) {
            return 0;
        }
        if (node == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, node) != 7) {
            return 0;
        }
        int left = emon.Port.CellsAt(idx, 3);
        if (left <= 0) {
            return 0;
        }
        emon.Port.CellsSet(idx, 3, left - 1);
        int nums = PxDget(src, ar, dc, a, b, st, node, Pdfxnames.PxNums());
        int kids = Pdfdoc.PdDget(src, ar, dc, a, b, st, node, Pdfnames.PnKids());
        int k = 0;
        int v = 0;
        int kr = 0;
        if ((nums != 0) && (Pdflex.PlKindOf(ar, nums) == 6)) {
            k = Pdflex.PlFirst(ar, nums);
            while (k != 0) {
                v = Pdflex.PlNext(ar, k);
                if (v == 0) {
                    k = 0;
                } else {
                    kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                    if ((kr != 0) && (Pdflex.PlKindOf(ar, kr) == 2)) {
                        emon.Port.CellsPush(@out, Pdflex.PlIntValue(ar, kr));
                        emon.Port.CellsPush(@out, v);
                    }
                    k = Pdflex.PlNext(ar, v);
                }
            }
        }
        if ((kids != 0) && (Pdflex.PlKindOf(ar, kids) == 6)) {
            k = Pdflex.PlFirst(ar, kids);
            while (k != 0) {
                kr = Pdfdoc.PdResolve(src, ar, dc, a, b, st, k);
                PxNnCollect(src, ar, dc, a, b, st, idx, kr, depth + 1, @out);
                k = Pdflex.PlNext(ar, k);
            }
        }
        return 0;
    }
    public static int PxDestInit(emon.Port.Cells @out, int at) {
        // A destination record (8 cells at `at`) that says nothing: page -1, kind 0,
        // four null parameters, no name.
        emon.Port.CellsSet(@out, at, -1);
        emon.Port.CellsSet(@out, at + 1, 0);
        emon.Port.CellsSet(@out, at + 2, PxNone);
        emon.Port.CellsSet(@out, at + 3, PxNone);
        emon.Port.CellsSet(@out, at + 4, PxNone);
        emon.Port.CellsSet(@out, at + 5, PxNone);
        emon.Port.CellsSet(@out, at + 6, -1);
        emon.Port.CellsSet(@out, at + 7, 0);
        return 0;
    }
    internal static int PxDestKindOf(emon.Port.Cells ar, int h) {
        // A fit name as a `ds-kind`, 0 when it is not one.
        if (h == 0) {
            return 0;
        }
        if (PxIs(ar, h, Pdfxnames.PxXyz()) == 1) {
            return 1;
        }
        if (PxIs(ar, h, Pdfxnames.PxFit()) == 1) {
            return 2;
        }
        if (PxIs(ar, h, Pdfxnames.PxFitH()) == 1) {
            return 3;
        }
        if (PxIs(ar, h, Pdfxnames.PxFitV()) == 1) {
            return 4;
        }
        if (PxIs(ar, h, Pdfxnames.PxFitR()) == 1) {
            return 5;
        }
        if (PxIs(ar, h, Pdfxnames.PxFitB()) == 1) {
            return 6;
        }
        if (PxIs(ar, h, Pdfxnames.PxFitBh()) == 1) {
            return 7;
        }
        if (PxIs(ar, h, Pdfxnames.PxFitBv()) == 1) {
            return 8;
        }
        return 0;
    }
    public static int PxRemoteSet(emon.Port.Cells idx, int on) {
        // While `on` is 1 a destination's integer page is a REMOTE document's 0-based page
        // (a GoToR action) and is kept as it is; while 0 it must name a page of this document.
        emon.Port.CellsSet(idx, 5, on);
        return 0;
    }
    internal static int PxDestArray(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, int arr, emon.Port.Cells @out, int at) {
        // Fill a destination record from `[page /Fit... params]`. The page is the RAW
        // first element: a reference names a page by object number (resolving it would
        // lose that); an integer is a 0-based page INDEX, which the spec allows only in a
        // remote destination but wkhtmltopdf and others write in local ones, and poppler and
        // pdf.js follow: here it is taken as a page of this document when it is one (in
        // range), and always in remote mode (`px-remote-set`), and the record says so by
        // adding 16 to its kind. Answers 1 when a page was found, else 0 (the record keeps
        // what was read).
        int e0 = Pdflex.PlFirst(ar, arr);
        int e = 0;
        int j = 0;
        int v = 0;
        int isint = 0;
        int got = 0;
        if (e0 == 0) {
            return 0;
        }
        if (Pdflex.PlKindOf(ar, e0) == 9) {
            emon.Port.CellsSet(@out, at, PxPageOf(idx, Pdflex.PlIntValue(ar, e0)));
            if (PxPageOf(idx, Pdflex.PlIntValue(ar, e0)) >= 0) {
                got = 1;
            }
        }
        if (Pdflex.PlKindOf(ar, e0) == 2) {
            v = Pdflex.PlIntValue(ar, e0);
            isint = 16;
            if (emon.Port.CellsAt(idx, 5) == 1) {
                emon.Port.CellsSet(@out, at, v);
                got = 1;
            } else if ((v >= 0) && (v < emon.Port.CellsAt(idx, 0))) {
                emon.Port.CellsSet(@out, at, v);
                got = 1;
            }
        }
        e = Pdflex.PlNext(ar, e0);
        emon.Port.CellsSet(@out, at + 1, isint);
        if (e == 0) {
            return got;
        }
        v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
        emon.Port.CellsSet(@out, at + 1, PxDestKindOf(ar, v) + isint);
        e = Pdflex.PlNext(ar, e);
        j = 0;
        while ((e != 0) && (j < 4)) {
            v = Pdfdoc.PdResolve(src, ar, dc, a, b, st, e);
            if (PxIsNum(ar, v) == 1) {
                emon.Port.CellsSet(@out, at + (2 + j), PxClampCp(Pdflex.PlNumCp(ar, v)));
            }
            e = Pdflex.PlNext(ar, e);
            j += 1;
        }
        return got;
    }
    internal static int PxDestValue(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells pg, emon.Port.Cells txt, int h0, emon.Port.Cells @out, int at, int depth) {
        // A destination from a /Dest or /D value: an array, a dictionary whose /D is one,
        // or a NAME (or string) looked up in the old /Dests dictionary and the name tree.
        // The name is kept in the record as a run of `txt` (at the first level). Answers
        // 1 when a page (or remote page number) was found.
        if (h0 == 0) {
            return 0;
        }
        if (depth > 3) {
            return 0;
        }
        int h = Pdfdoc.PdResolve(src, ar, dc, a, b, st, h0);
        int kind = 0;
        int v = 0;
        int got = 0;
        int dd = 0;
        int d = 0;
        if (h == 0) {
            return 0;
        }
        kind = Pdflex.PlKindOf(ar, h);
        if (kind == 6) {
            return PxDestArray(src, ar, dc, a, b, st, idx, h, @out, at);
        }
        if (kind == 7) {
            d = PxGet(ar, h, Pdfxnames.PxD());
            return PxDestValue(src, ar, dc, a, b, st, idx, pg, txt, d, @out, at, depth + 1);
        }
        if ((kind == 4) || (kind == 5)) {
            if (depth == 0) {
                emon.Port.CellsSet(@out, at + 6, emon.Port.CellsLen(txt));
                PxTextPush(ar, h, txt);
                emon.Port.CellsSet(@out, at + 7, emon.Port.CellsLen(txt) - emon.Port.CellsAt(@out, at + 6));
            }
            if (kind == 4) {
                dd = emon.Port.CellsAt(idx, 1);
                v = PxDictFindBytes(ar, idx, dd, h);
                if (v == 0) {
                    v = PxNtFind(src, ar, dc, a, b, st, idx, h);
                }
            } else {
                v = PxNtFind(src, ar, dc, a, b, st, idx, h);
                dd = emon.Port.CellsAt(idx, 1);
                if (v == 0) {
                    v = PxDictFindBytes(ar, idx, dd, h);
                }
            }
            if (v == 0) {
                return 0;
            }
            return PxDestValue(src, ar, dc, a, b, st, idx, pg, txt, v, @out, at, depth + 1);
        }
        return got;
    }
    public static int PxDestOf(emon.Port.Src src, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells idx, emon.Port.Cells pg, emon.Port.Cells txt, int h, emon.Port.Cells @out, int at) {
        // Read the destination `h` (a /Dest or /D value, raw) into the 8-cell record at
        // `at` of `out` (initialized here): page (index, or the remote page number; -1
        // unresolved), `ds-kind`, four parameters in centipoints of the target page's
        // user space (`PX_NONE` for null or absent), and the destination's name as a run of
        // `txt` (-1 0 when it was not named). Answers 1 when a page was found.
        PxDestInit(@out, at);
        return PxDestValue(src, ar, dc, a, b, st, idx, pg, txt, h, @out, at, 0);
    }
    public static int PxJsonHex2(System.Text.StringBuilder t, int v) {
        int hi = v / 16;
        int lo = v % 16;
        if (hi < 10) {
            emon.Port.TextCp(t, 48 + hi);
        } else {
            emon.Port.TextCp(t, 87 + hi);
        }
        if (lo < 10) {
            emon.Port.TextCp(t, 48 + lo);
        } else {
            emon.Port.TextCp(t, 87 + lo);
        }
        return 0;
    }
    public static int PxJsonEscCp(System.Text.StringBuilder t, int c) {
        // One code point as the inside of a JSON string: quote, backslash and control
        // characters escaped (a backslash, u, 00 and two lower-case hex digits), everything else as UTF-8.
        if (c == 34) {
            emon.Port.TextAscii(t, "\\\"");
        }
        if (c == 92) {
            emon.Port.TextAscii(t, "\\\\");
        }
        if ((c != 34) && (c != 92)) {
            if (c < 32) {
                emon.Port.TextAscii(t, "\\u00");
                PxJsonHex2(t, c);
            } else {
                emon.Port.TextCp(t, c);
            }
        }
        return 0;
    }
    public static int PxJsonRun(System.Text.StringBuilder t, emon.Port.Cells txt, int s, int n) {
        // A run of `txt` as a JSON string: quote, backslash and control characters
        // escaped (backslash, u, 00 and two lower-case hex digits), everything else as UTF-8. A run that is absent
        // (start -1) is `null`.
        if (s < 0) {
            emon.Port.TextAscii(t, "null");
            return 0;
        }
        int i = 0;
        int c = 0;
        emon.Port.TextAscii(t, "\"");
        while (i < n) {
            c = emon.Port.CellsAt(txt, s + i);
            PxJsonEscCp(t, c);
            i += 1;
        }
        emon.Port.TextAscii(t, "\"");
        return 0;
    }
    public static int PxJsonCp(System.Text.StringBuilder t, int v) {
        // A centipoint value as a JSON number (SPEC 4.3): 7250 is 72.5, -5 is -0.05, 0 is 0,
        // no trailing zeros; `PX_NONE` is `null`.
        int m = v;
        int frac = 0;
        if (v == PxNone) {
            emon.Port.TextAscii(t, "null");
            return 0;
        }
        if (m < 0) {
            emon.Port.TextAscii(t, "-");
            m = 0 - m;
        }
        emon.Port.TextI32(t, m / 100);
        frac = m % 100;
        if (frac != 0) {
            emon.Port.TextAscii(t, ".");
            emon.Port.TextCp(t, 48 + (frac / 10));
            if ((frac % 10) != 0) {
                emon.Port.TextCp(t, 48 + (frac % 10));
            }
        }
        return 0;
    }
    public static int PxJsonBox(System.Text.StringBuilder t, emon.Port.Cells c, int at) {
        // Four centipoint values of `c` from `at` as a JSON array.
        emon.Port.TextAscii(t, "[");
        PxJsonCp(t, emon.Port.CellsAt(c, at));
        emon.Port.TextAscii(t, ",");
        PxJsonCp(t, emon.Port.CellsAt(c, at + 1));
        emon.Port.TextAscii(t, ",");
        PxJsonCp(t, emon.Port.CellsAt(c, at + 2));
        emon.Port.TextAscii(t, ",");
        PxJsonCp(t, emon.Port.CellsAt(c, at + 3));
        emon.Port.TextAscii(t, "]");
        return 0;
    }
    public static int PxDestPresent(emon.Port.Cells c, int at) {
        // 1 when the destination record at c[at] holds anything.
        if (emon.Port.CellsAt(c, at) != -1) {
            return 1;
        }
        if (emon.Port.CellsAt(c, at + 1) != 0) {
            return 1;
        }
        if (emon.Port.CellsAt(c, at + 6) >= 0) {
            return 1;
        }
        return 0;
    }
    public static int PxJsonDest(System.Text.StringBuilder t, emon.Port.Cells txt, emon.Port.Cells c, int at) {
        // A destination record as a JSON object: the page (0-based, -1 unresolved), the
        // fit, its arguments in the PDF's own order (trailing nulls dropped) and its name.
        int last = -1;
        int k = 0;
        emon.Port.TextAscii(t, "{\"page\":");
        emon.Port.TextI32(t, emon.Port.CellsAt(c, at));
        emon.Port.TextAscii(t, ",\"fit\":\"");
        DsKindEmitName(t, emon.Port.CellsAt(c, at + 1) % 16);
        emon.Port.TextAscii(t, "\"");
        if (emon.Port.CellsAt(c, at + 1) >= 16) {
            emon.Port.TextAscii(t, ",\"index\":true");
        }
        while (k < 4) {
            if (emon.Port.CellsAt(c, (at + 2) + k) != PxNone) {
                last = k;
            }
            k += 1;
        }
        if (last >= 0) {
            emon.Port.TextAscii(t, ",\"args\":[");
            k = 0;
            while (k <= last) {
                if (k > 0) {
                    emon.Port.TextAscii(t, ",");
                }
                PxJsonCp(t, emon.Port.CellsAt(c, (at + 2) + k));
                k += 1;
            }
            emon.Port.TextAscii(t, "]");
        }
        if (emon.Port.CellsAt(c, at + 6) >= 0) {
            emon.Port.TextAscii(t, ",\"name\":");
            PxJsonRun(t, txt, emon.Port.CellsAt(c, at + 6), emon.Port.CellsAt(c, at + 7));
        }
        emon.Port.TextAscii(t, "}");
        return 0;
    }
}
